    if (act === 'move-plan-order') { D.requireHost(state, u(), r); const list = [...(view.finalOrderDrafts[r.id] || D.ranked(r).map(x => x.id))], i = Number(el.dataset.index), j = i + Number(el.dataset.dir); if (j >= 0 && j < list.length) [list[i], list[j]] = [list[j], list[i]]; view.finalOrderDrafts[r.id] = list; return render(); }
