    if (act === 'delete-moment') return confirm('Xóa ảnh ở mọi nơi', 'Ảnh biến mất khỏi dòng cá nhân, album và tham chiếu trong tin nhắn. Đoạn chữ tin nhắn vẫn còn. Không khôi phục trong bản đầu.', 'delete-moment-confirm', `data-id="${id}"`, true);
