    if (act === 'report') return openModal('Báo cáo nội dung', `<form data-form="report" data-target="${el.dataset.type}" data-id="${id}"><label class="field">Lý do<select name="reason"><option value="PRIVACY">Quyền riêng tư</option><option value="HARASSMENT">Quấy rối</option><option value="INAPPROPRIATE">Nội dung không phù hợp</option><option value="SPAM">Spam</option><option value="OTHER">Khác</option></select></label><label class="field">Mô tả thêm<textarea name="text" maxlength="2000"></textarea></label><p class="tiny">Báo cáo mẫu không công khai với nhóm. Chủ phòng không được đọc tin nhắn riêng bị báo cáo.</p>${formEnd('Ghi nhận báo cáo mẫu')}</form>`);
    if (act === 'expense-form') return expenseForm(id);
