    if (act === 'settlement-form') return openModal('Ghi nhận bạn đã chuyển tiền', `<form data-form="settlement" data-to="${el.dataset.to}"><p class="sub">${esc(person(u()).name)} → ${esc(person(el.dataset.to).name)}. Chỉ ghi sổ, không chuyển tiền thật.</p><label class="field">Số tiền thực tế đã chuyển<input type="number" name="amount" required min="1" step="1" value="${el.dataset.amount}"></label><p class="callout">Có thể ghi một phần. Số dư chưa đổi cho đến khi người nhận xác nhận.</p>${formEnd('Báo đã chuyển, chờ xác nhận')}</form>`);
    if (act === 'member-actions') return openModal(`Thành viên ${person(id).name}`, `<div class="row wrap">${btn('Đề nghị chuyển quyền chủ phòng', 'request-host', 'soft', `data-id="${id}"`)}${btn('Mời ra khỏi phòng', 'kick-prompt', 'danger', `data-id="${id}"`)}</div><p class="tiny mt">Chuyển quyền chỉ có hiệu lực khi người nhận đồng ý. Mời ra khỏi phòng thu hồi quyền album, không tự xóa ảnh tác giả.</p>`);
