    if (act === 'notifications') { const list = state.notifications.filter(n => n.userId === u()); return openModal('Thông báo của bạn', list.map(n => `<button class="notice-item ${n.read ? '' : 'unread'}" style="width:100%;text-align:left" data-act="open-notification" data-id="${n.id}">${icon(n.targetType === 'PHOTO' ? 'gallery' : 'chat', 19)}<span><p>${esc(n.title)}</p><small class="tiny">${ago(n.createdAt)} · chạm để xem, quyền luôn được kiểm lại</small></span></button>`).join('') || '<p class="sub">Chưa có thông báo.</p>'); }
    if (act === 'slot-form') return openModal('Góp một khung giờ', `<form data-form="slot"><label class="field">Ngày và giờ bạn đề xuất<input type="datetime-local" name="startsAt" required></label><p class="tiny">Thêm giờ không xóa lựa chọn hoặc thảo luận đang có.</p>${formEnd('Thêm khung giờ')}</form>`);
    if (act === 'slot-comments') return openModal('Thảo luận khung giờ ẩn tên', `${r.slotComments.filter(x => x.slotId === id).map(c => `<div class="comment-item"><span class="grow"><strong>${c.ownerId === u() ? 'Bạn' : 'Thành viên ẩn tên'}</strong><p>${esc(c.text)}</p></span></div>`).join('')}<form data-form="slot-comment" data-id="${id}"><label class="field">Ý kiến về khung giờ<textarea name="text" required maxlength="500"></textarea></label>${formEnd('Gửi thảo luận ẩn tên')}</form>`);
    if (act === 'calendar') { const start = new Date(`${r.date}T${r.time}:00+07:00`); D.check(Number.isFinite(start.getTime()), 'VALIDATION', 'Chọn ngày và giờ hợp lệ trước.'); const stamp = n => new Date(n).toISOString().replace(/[-:]/g, '').replace(/\.\d{3}/, ''); const ics = ['BEGIN:VCALENDAR', 'VERSION:2.0', 'PRODID:-//Keo Prototype//VI', 'BEGIN:VEVENT', `UID:${r.id}-prototype@keo.local`, `DTSTAMP:${stamp(Date.now())}`, `DTSTART:${stamp(start.getTime())}`, `DTEND:${stamp(start.getTime() + 2 * D.HOUR)}`, `SUMMARY:${r.name.replace(/[\r\n;,]/g, ' ')}`, `LOCATION:${r.region.replace(/[\r\n;,]/g, ' ')}`, 'END:VEVENT', 'END:VCALENDAR'].join('\r\n'); const url = URL.createObjectURL(new Blob([ics], { type: 'text/calendar;charset=utf-8' })); const a = document.createElement('a'); a.href = url; a.download = 'keo-cuoc-hen.ics'; a.click(); setTimeout(() => URL.revokeObjectURL(url), 5000); return toast('Đã tạo tệp lịch để bạn tự thêm vào ứng dụng lịch.'); }
    online();
    if (act === 'invite-lock') { D.requireHost(state, u(), r); r.inviteLocked = !r.inviteLocked; closeModal(); }
    else if (act === 'react') { D.react(state, u(), id, el.dataset.type); save(); if ($('modal').open && $('modal').dataset.photoId === id) photoDetail(id); render(); return; }
    else if (act === 'delete-comment') { const c = state.comments.find(x => x.id === id), targetId = c.targetId, kind = c.kind; D.deleteComment(state, u(), id, c.authorId !== u() ? 'Chủ phòng gỡ trong prototype' : null); save(); if (kind === 'PHOTO' && $('modal').open) photoDetail(targetId); render(); return; }
    else if (act === 'remove-place-confirm') { D.removePlace(state, u(), id); closeModal(); }
    else if (act === 'delete-moment-confirm') { D.deleteMoment(state, u(), id); closeModal(); }
    else if (act === 'relation') { D.changeRelation(state, u(), id, el.dataset.action); closeModal(); }
    else if (act === 'recall') D.recall(state, u(), id);
    else if (act === 'vote') D.vote(state, u(), r.id, id, Number(value));
    else if (act === 'submit-votes') D.submitVotes(state, u(), r.id);
    else if (act === 'delete-idea') D.deleteIdea(state, u(), r.id, id);
    else if (act === 'endorse') { D.requireMember(state, u(), r); D.check(r.lifecycle === 'ACTIVE', 'INVALID_STATE', 'Kèo đã kết thúc hoặc lưu trữ.'); const i = r.ideas.find(x => x.id === id); D.check(i.ownerId !== u(), 'NO_ACCESS', 'Không tự hưởng ứng ý của mình.'); i.endorsements = i.endorsements.includes(u()) ? i.endorsements.filter(v => v !== u()) : [...i.endorsements, u()]; }
    else if (act === 'select-idea') { D.selectIdea(state, u(), r.id, id); view.orderDrafts = {}; view.finalOrderDrafts = {}; }
    else if (act === 'lock-shortlist') { D.lockShortlist(state, u(), r.id); view.orderDrafts = {}; view.finalOrderDrafts = {}; }
    else if (act === 'submit-order') D.submitOrder(state, u(), r.id, view.orderDrafts[`${r.id}:${u()}`] || r.selected);
    else if (act === 'seal-plan-confirm') { const order = view.finalOrderDrafts[r.id] || D.ranked(r).map(x => x.id); D.publishPlan(state, u(), r.id, { order, time: el.dataset.time, reason: el.dataset.reason || '' }); view.planPanel = 'timeline'; closeModal(); }
    else if (act === 'complete') { D.requireMember(state, u(), r); D.check(r.planVersion > 0 && r.order.includes(id) && r.lifecycle === 'ACTIVE', 'INVALID_STATE', 'Hoạt động không thuộc lịch đang đi hoặc kèo đã đóng.'); const i = r.ideas.find(i => i.id === id); i.completed = !i.completed; i.completedBy = u(); }
    else if (act === 'note-handled') { D.requireHost(state, u(), r); D.check(r.lifecycle === 'ACTIVE', 'INVALID_STATE', 'Kèo hiện chỉ đọc.'); const n = r.notes.find(n => n.id === id); n.handled = !n.handled; }
    else if (act === 'lifecycle-confirm') { D.lifecycle(state, u(), r.id, el.dataset.action); closeModal(); }
    else if (act === 'leave-confirm') { D.leave(state, u(), r.id); closeModal(); view.page = 'rooms'; }
    else if (act === 'kick-confirm') { D.leave(state, u(), r.id, id); closeModal(); }
    else if (act === 'request-host') { D.requireHost(state, u(), r); D.check(r.members.includes(id), 'NO_ACCESS', 'Người nhận phải còn trong phòng.'); r.hostTransfer = { to: id, from: u() }; closeModal(); }
    else if (act === 'accept-host') { D.requireMember(state, u(), r); D.check(r.hostTransfer?.to === u(), 'NO_ACCESS', 'Không có lời chuyển quyền cho bạn.'); r.hostId = u(); delete r.hostTransfer; }
